const c=require('./common');
(async()=>{try{let repo=process.env.CACHE_REPOSITORY||c.input('repository'),dry=process.argv.includes('--dry-run')||process.env.DRY_RUN!=='false',grace=Number(process.env.GRACE_DAYS||7)*86400000, m=await c.refs(repo),live=new Set(Object.values(m.json.references).map(x=>x.object));let all=(await c.assets(repo)).assets,now=Date.now();for(let a of all.filter(x=>x.name.endsWith('.tar.zst'))){let h='sha256:'+a.name.slice(0,-8);let old=now-new Date(a.created_at).getTime()>grace;if(!live.has(h)&&old){console.log(`${dry?'would delete':'delete'} ${a.name}`);if(!dry)await c.gh(`/repos/${repo}/releases/assets/${a.id}`,{method:'DELETE'})}}}catch(e){c.fail(e)}})();
